// Veredicto estructurado -> reglas de umbral del negocio.
const caso = $('Armar input del Juez').first().json;
const v = ($json.output && typeof $json.output === 'object') ? $json.output : {};
let ex = parseInt(v.exactitud_factual, 10);
if (!Number.isFinite(ex)) ex = 1;
ex = Math.min(5, Math.max(1, ex));
let estado = ['ACEPTADO', 'CORREGIR', 'RECHAZADO'].includes(v.estado_veredicto) ? v.estado_veredicto : 'RECHAZADO';
if (estado === 'ACEPTADO' && ex < 4) estado = 'CORREGIR';   // ACEPTADO exige exactitud >= 4
if (estado === 'CORREGIR' && ex === 1) estado = 'RECHAZADO'; // con exactitud 1 no se reintenta
const intento = Number(caso.intento || 1);
const esAccion = caso.tipo_caso === 'ACCION';  // una acción no se corrige sola: se congela
const ruta = estado === 'ACEPTADO' ? 'aceptar'
  : esAccion ? 'escalar (acción congelada)'
  : estado === 'CORREGIR' ? (intento <= 2 ? 'corregir' : 'escalar (tope de reintentos)')
  : 'escalar';
const { input_juez, ...resto } = caso;
return [{ json: { ...resto, exactitud_factual: ex, estado_veredicto: estado, critica: String(v.critica || ''), ruta } }];

// El Juez no devolvió JSON válido: nunca se deja pasar una respuesta sin juzgar.
const caso = $('Armar input del Juez').first().json;
const { input_juez, ...resto } = caso;
return [{ json: { ...resto, exactitud_factual: 1, estado_veredicto: 'RECHAZADO',
  critica: 'El Juez no devolvió un JSON válido: se escala a revisión humana.', ruta: 'escalar' } }];

// Devuelve el veredicto (no la fila de Sheets) al workflow que llamó.
const a = $('Normalizar veredicto').all();
return a.length ? a : $('Veredicto inválido → escalar').all();

// Log de auditoría máquina-procesable (JSON) del Juez, con enmascarado de PII antes de guardarlo.
const v = $json;
// Nombres del paciente: los que extrajo el sistema y los que el paciente dice ("soy…", "me llamo…", "mi nombre es…").
const datosClave = String((v.contexto_airtable || {}).datos_clave || '');
const delMemoria = datosClave.match(/Paciente:\s*([^|]+)/);
const nombres = [(v.accion_propuesta || {}).nombre, delMemoria ? delMemoria[1] : '']
  .map(x => String(x || '').trim()).filter(x => x.length > 2);
const esc = x => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const enmascarar = s => nombres.reduce((t, nm) => t.replace(new RegExp(esc(nm), 'gi'), '[NOMBRE]'), String(s || ''))
  .replace(/\b(soy|me llamo|mi nombre es)\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+)?/g, '$1 [NOMBRE]')
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[EMAIL]')
  .replace(/\b\d{1,2}\.\d{3}\.\d{3}\b|\b\d{7,8}\b/g, '[DNI]')
  .replace(/\+?\d[\d\s-]{8,}\d/g, '[TEL]');
const log = {
  timestamp: new Date().toISOString(),
  traceId: v.traceId || 'sin-traceId',
  parentExecutionId: String(v.execution_id || ''),
  executionId: String($execution.id),
  environment: 'desarrollo (n8n local)',
  nodeName: 'AgendaBot · Juez (supervisor) › Juez (LLM con JSON Schema)',
  agentNode: v.tipo_caso === 'ACCION' ? 'Router + Resolver accion (acción propuesta)' : 'Agente RAG (Consultas)',
  toolOutput: enmascarar(v.fragmentos).slice(0, 1500),
  systemPromptSnapshot: { version: 'juez-rubrica-v3.1 (acciones + «No sé»)', sha256: '5d369ceb1dc7' },
  confidenceScore: Math.round((Number(v.exactitud_factual) || 1) / 5 * 100) / 100,
  decision: { estado_veredicto: v.estado_veredicto, ruta: v.ruta, intento: v.intento || 1 },
};
return [{ json: { ...v, ...log, pregunta: enmascarar(v.pregunta), respuesta: enmascarar(v.respuesta),
  systemPromptSnapshot: log.systemPromptSnapshot.version + ' · sha256:' + log.systemPromptSnapshot.sha256,
  log_json: JSON.stringify(log) } }];
